          <div>
            <h1 className="text-3xl font-bold tracking-tight">{activeTab === 'settings' ? 'Settings' : activeTab === 'movements' ? 'Movements' : 'Financial Analytics'}</h1>
            <p className="text-txt-secondary mt-1 font-medium">{activeTab === 'settings' ? 'Global preferences.' : activeTab === 'movements' ? 'Categorize and manage.' : 'Insights & trends.'}</p>
          </div>
          <div className="flex items-center gap-4">
            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-txt-secondary" size={18} />
              <input type="text" placeholder="Search data..." className="bg-surface pl-12 pr-6 py-3 rounded-full shadow-soft focus:outline-none focus:ring-2 focus:ring-primary-start/20 w-64 transition-colors duration-300" />
            </div>
          </div>
        </header>

        {activeTab === 'dashboard' ? renderDashboard() : activeTab === 'movements' ? renderMovements() : activeTab === 'documents' ? renderDocuments() : activeTab === 'settings' ? renderSettings() : null}

        {activeTab === 'dashboard' && (
          <section className="mt-10">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-bold text-left">Recent Activity</h3>
              <button onClick={() => setActiveTab('movements')} className="text-primary-end font-bold text-sm hover:underline">Full History</button>
            </div>
            <div className="bg-surface rounded-3xl shadow-soft overflow-hidden transition-colors duration-300">
              {transactions.length > 0 ? transactions.slice(0, 5).map((tx, idx) => (
                <div key={idx} className="flex items-center justify-between p-6 hover:bg-slate-50 transition-colors border-b border-slate-50 last:border-0">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-canvas rounded-xl flex items-center justify-center text-txt-secondary transition-colors duration-300"><DollarSign size={18} /></div>
                    <div className="text-left"><p className="font-bold text-txt-primary leading-tight">{tx.operation}</p><p className="text-xs text-txt-secondary mt-1 font-semibold">{new Date(tx.date).toLocaleDateString()}</p></div>
                  </div>
                  <div className="text-right">
                    <p className={`font-bold ${tx.amount > 0 ? 'text-emerald-600' : 'text-txt-primary'}`}>{tx.amount > 0 ? '+' : ''}{tx.amount.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})} €</p>
                    <p className="text-[10px] uppercase font-bold tracking-widest text-txt-secondary mt-1 opacity-60">{tx.category}</p>
                  </div>
                </div>
              )) : <div className="p-12 text-center text-txt-secondary italic">Ready for import.</div>}
            </div>
          </section>
        )}
      </main>

      {/* Transaction Modal */}
      {showModal && editingTx && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-surface w-full max-w-lg rounded-[32px] shadow-2xl p-8 animate-in fade-in zoom-in duration-200 border border-white/10">
            <div className="flex items-center justify-between mb-8 px-2">
              <h3 className="text-2xl font-bold">{editingTx.id ? 'Edit Entry' : 'Manual Entry'}</h3>
              <button onClick={() => setShowModal(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors"><X size={24} /></button>
            </div>
            <form onSubmit={handleSaveTx} className="space-y-6 text-left">
              <div className="grid grid-cols-2 gap-4 px-2">
                <div className="space-y-2">
                  <label className="text-xs font-bold text-txt-secondary uppercase tracking-widest ml-1">Date</label>
                  <input type="date" value={editingTx.date} onChange={(e) => setEditingTx({...editingTx, date: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-4 focus:ring-2 focus:ring-primary-start/20 outline-none font-medium" required />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-txt-secondary uppercase tracking-widest ml-1">Amount (€)</label>
                  <input type="number" step="0.01" value={editingTx.amount} onChange={(e) => setEditingTx({...editingTx, amount: parseFloat(e.target.value)})} className="w-full bg-slate-50 border-none rounded-2xl p-4 focus:ring-2 focus:ring-primary-start/20 outline-none font-bold text-lg" required />
                </div>
              </div>
              <div className="space-y-2 px-2">
                <label className="text-xs font-bold text-txt-secondary uppercase tracking-widest ml-1">Operation</label>
                <input type="text" value={editingTx.operation} onChange={(e) => setEditingTx({...editingTx, operation: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-4 focus:ring-2 focus:ring-primary-start/20 outline-none font-bold" placeholder="Reference Name" required />
              </div>
              <div className="grid grid-cols-2 gap-4 px-2">
                <div className="space-y-2">
                  <label className="text-xs font-bold text-txt-secondary uppercase tracking-widest ml-1">Category</label>
                  <select value={editingTx.category} onChange={(e) => setEditingTx({...editingTx, category: e.target.value, subcategory: 'None'})} className="w-full bg-slate-50 border-none rounded-2xl p-4 outline-none font-bold">
                    <option value="Uncategorized">Uncategorized</option>
                    {Object.keys(categories).map(c => <option key={c} value={c}>{c}</option>)}
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-bold text-txt-secondary uppercase tracking-widest ml-1">Subcategory</label>
                  <select value={editingTx.subcategory} onChange={(e) => setEditingTx({...editingTx, subcategory: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-4 outline-none font-bold">
                    <option value="None">None</option>
                    {categories[editingTx.category] && categories[editingTx.category].map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                </div>
              </div>
              <div className="pt-4 flex gap-4 px-2">
                <button type="button" onClick={() => setShowModal(false)} className="flex-1 bg-slate-100 hover:bg-slate-200 text-txt-primary font-bold py-4 rounded-2xl transition-all">Cancel</button>
                <button type="submit" className="flex-1 glass-gradient text-white font-bold py-4 rounded-2xl shadow-brand transition-transform hover:scale-[1.02] flex items-center justify-center gap-2"><Save size={20} /> Update</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;

